import { afterAll, beforeAll, describe, expect, test } from "bun:test";
// @ts-expect-error jsdom is intentionally untyped in this project.
import { JSDOM } from "jsdom";
import type { Editor } from "@tiptap/core";
import { createTypstSession, type TypstSessionState, type TypstSessionDependencies } from "./session";
import { htmlToTypst } from "./document";
import { FOLIO_CONTENT_SAVED, type FolioContentSnapshot } from "../idb";
import type { ExportPayload } from "../exchange";

const previous = new Map<string, PropertyDescriptor | undefined>();
beforeAll(() => {
  const dom = new JSDOM('',{url:'https://twyne.test'});
  for (const key of ['window','document','DOMParser','CustomEvent']) {
    previous.set(key,Object.getOwnPropertyDescriptor(globalThis,key));
    Object.defineProperty(globalThis,key,{configurable:true,value:dom.window[key]});
  }
});
afterAll(() => { for(const [key, descriptor] of previous) { if(descriptor) Object.defineProperty(globalThis,key,descriptor); else Reflect.deleteProperty(globalThis,key); } });

async function setup(overrides: Partial<TypstSessionDependencies> = {}) {
  let html = '<p>Initial</p>';
  let editable = true;
  const listeners = new Set<() => void>();
  const states: TypstSessionState[] = [];
  const saved: string[] = [];
  let snap: FolioContentSnapshot = {folioId:'folio',html,typstSource:htmlToTypst(html),format:'typst',updatedAt:1};
  const editor = {
    getHTML: () => html,
    setEditable: (value:boolean) => { editable=value; },
    on: (_:string,callback:()=>void) => listeners.add(callback),
    off: (_:string,callback:()=>void) => listeners.delete(callback),
    commands:{setContent: (value:string,options:{emitUpdate:boolean})=>{html=value;if(options.emitUpdate) listeners.forEach(fn=>fn());}},
    isDestroyed:false,
  } as unknown as Editor;
  const session = await createTypstSession({editor,folioId:'folio',readOnly:false,onState:state=>states.push(state),onPages:()=>{},getPayload:async()=>({html,title:'Test'}) as ExportPayload},{
    loadSnapshot:async()=>snap,
    saveSource:async(_id,source,body,expected)=>{if((snap.typstSource??null)!==expected)throw new Error('The manuscript changed');saved.push(source);snap={...snap,typstSource:source,html:body!};},
    loadDraft:async()=>null,
    saveDraft:async()=>{},
    clearDraft:async()=>{},
    compile:async()=>({pdf:new Blob(['PDF']),pages:['<svg xmlns="http://www.w3.org/2000/svg"/>'],pageCount:1}),
    ...overrides,
  });
  return {session,states,saved,get html(){return html;},get editable(){return editable;},edit(value:string){html=value;listeners.forEach(fn=>fn());},setSnapshot(value:FolioContentSnapshot){snap=value;},get snapshot(){return snap;}};
}

describe('Typst source session',()=>{
  test('only a successfully compiled source replaces the manuscript',async()=>{
    let fail = true;
    const t=await setup({compile:async()=>{if(fail)throw new Error('Syntax error at line 1');return {pdf:new Blob(['PDF']),pages:[],pageCount:1};}});
    try {
      t.session.changeSource('= New title');
      expect(t.editable).toBe(false);
      await t.session.apply();
      expect(t.html).toBe('<p>Initial</p>');
      expect(t.saved).toHaveLength(0);
      expect(t.states.at(-1)?.error).toContain('Syntax error');
      fail=false;
      await t.session.apply();
      expect(t.html).toBe('<h1>New title</h1>');
      expect(t.saved).toEqual(['= New title']);
      expect(t.editable).toBe(true);
    } finally {t.session.destroy();}
  });
  test('a delayed visual save never overwrites later keystrokes',async()=>{
    const t=await setup();
    try {
      t.edit('<p>First edit</p>');
      const first={...t.snapshot,html:t.html,typstSource:htmlToTypst(t.html)};
      t.edit('<p>Second edit</p>');
      window.dispatchEvent(new CustomEvent(FOLIO_CONTENT_SAVED,{detail:first}));
      expect(t.html).toBe('<p>Second edit</p>');
      expect(t.states.at(-1)?.source).toContain('Second edit');
    } finally {t.session.destroy();}
  });
  test('remote source conflicts preserve an unapplied draft',async()=>{
    const t=await setup();
    try {
      t.session.changeSource('My local source');
      window.dispatchEvent(new CustomEvent('twyne:typst-remote-change',{detail:{folioId:'folio',source:'Remote source',html:'<p>Remote source</p>'}}));
      expect(t.states.at(-1)?.conflict).toBe(true);
      expect(t.states.at(-1)?.source).toBe('My local source');
      expect(t.html).toBe('<p>Initial</p>');
      await t.session.apply();
      expect(t.saved).toHaveLength(0);
    } finally {t.session.destroy();}
  });
  test('recovers pending source and exposes it to export without replacing rich content',async()=>{
    const t=await setup({loadDraft:async()=>({folioId:'folio',source:'#broken(',baseSource:htmlToTypst('<p>Initial</p>'),updatedAt:1})});
    try {
      const detail={folioId:'folio',source:'',pending:false};
      window.dispatchEvent(new CustomEvent('twyne:request-typst-source',{detail}));
      expect(detail).toEqual({folioId:'folio',source:'#broken(',pending:true});
      expect(t.html).toBe('<p>Initial</p>');
      expect(t.editable).toBe(false);
      await t.session.discard();
      expect(t.states.at(-1)?.dirty).toBe(false);
      expect(t.editable).toBe(true);
    } finally {t.session.destroy();}
  });
});
